INSERT INTO opportunities(id,slug,kind,title,location,partner,active,sort_order) VALUES('trip-camino-de-santiago','trip-camino-de-santiago','trip','Camino de Santiago','Spain','Metro Relief and Hope Sojourns',1,65) ON CONFLICT(id) DO NOTHING;
INSERT INTO destinations(id,slug,title,location,eyebrow,summary,introduction,service,partners,focus,setting,notes,dates_text,image_url,image_alt,image_credit,status,sort_order,updated_at) VALUES('trip-camino-de-santiago','camino-de-santiago','Camino de Santiago','Spain','Make room for reflection','Walk the Camino de Santiago with Metro Relief and Hope Sojourns. Share steps, conversation, and reflection as this journey takes shape.','Explore the possibility of walking the Camino de Santiago together. This developing journey offers space to consider faith, community, and purpose through shared steps and meaningful conversation.','The route, itinerary, and daily activities will be shared as planning progresses.','Metro Relief connects its community with these journeys. Hope Sojourns helps coordinate planning and follows up with interested travelers.','Walking, community, faith, and reflection','A walking journey in Spain','Expressing interest is not a booking or a financial commitment. Dates, itinerary, cost, preparation requirements, and participation details are still being developed.','Dates and costs being planned · Interest conversations open','/assets/metro-journeys/camino-gala-program.png','Camino walkers on a rocky trail overlooking the coast','','published',65,strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO NOTHING;
INSERT INTO opportunities(id,slug,kind,title,location,partner,active,sort_order) VALUES('trip-kilimanjaro','trip-kilimanjaro','trip','Kilimanjaro','Tanzania','Metro Relief and Hope Sojourns',1,66) ON CONFLICT(id) DO NOTHING;
INSERT INTO destinations(id,slug,title,location,eyebrow,summary,introduction,service,partners,focus,setting,notes,dates_text,image_url,image_alt,image_credit,status,sort_order,updated_at) VALUES('trip-kilimanjaro','kilimanjaro','Kilimanjaro','Tanzania','A challenge with purpose','Explore a Kilimanjaro journey with Metro Relief and Hope Sojourns, centered on challenge, shared purpose, and connection.','Metro Relief and Hope Sojourns are developing a Kilimanjaro experience for travelers who want to take their next steps together. Share your interest to hear about the route, preparation, and participation details as plans develop.','The route, itinerary, and daily activities will be shared as planning progresses.','Metro Relief connects its community with these journeys. Hope Sojourns helps coordinate planning and follows up with interested travelers.','Challenge, shared purpose, and connection','A mountain trekking journey in Tanzania','Expressing interest is not a booking or a financial commitment. Dates, itinerary, cost, preparation requirements, and participation details are still being developed.','Dates and costs being planned · Interest conversations open','/assets/metro-journeys/kilimanjaro-gala-program.png','Hike for a Home participants together at the Kilimanjaro summit','','published',66,strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO NOTHING;
